<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { ApiClient, errorMessage } from '../api'
import { dateTime, localDateTime } from '../domain'
import type { NoticeSink, Product, Session } from '../types'
import DialogShell from '../components/DialogShell.vue'
import Icon from '../components/Icon.vue'
import HistoryDialog from './HistoryDialog.vue'
import type { KnowledgeRecord } from './types'
const props = defineProps<{ api: ApiClient; shopId: string; products: Product[]; sessions: Session[]; notify: NoticeSink; reload: () => Promise<void> }>()
const records = ref<KnowledgeRecord[]>([]), loading = ref(true), error = ref(''), formError = ref(''), open = ref(false), busy = ref(false), search = ref(''), showDeleted = ref(false)
const editing = ref<KnowledgeRecord | null>(null), history = ref<KnowledgeRecord | null>(null), deleting = ref<KnowledgeRecord | null>(null)
const form = reactive({ title: '', content: '', kind: 'faq' as 'faq' | 'memory', source: '', scope: 'shop' as 'shop' | 'product' | 'session', scopeId: '', expires: '' })
const filtered = computed(() => records.value.filter(r => (showDeleted.value || !r.deleted_at) && (r.title + ' ' + r.content).toLowerCase().includes(search.value.trim().toLowerCase())))
async function load() { loading.value = true; error.value = ''; try { records.value = await props.api.request<KnowledgeRecord[]>('/knowledge-records', { query: { shop_id: props.shopId } }) } catch (cause) { error.value = errorMessage(cause) } finally { loading.value = false } }
onMounted(load)
function edit(record: KnowledgeRecord | null) { editing.value = record; formError.value = ''; open.value = true; Object.assign(form, record ? { title: record.title, content: record.content, kind: record.kind, source: record.source, scope: record.scope, scopeId: record.scope_id ?? '', expires: localDateTime(record.expires_at) } : { title: '', content: '', kind: 'faq', source: '', scope: 'shop', scopeId: '', expires: '' }) }
function scopeName(record: KnowledgeRecord) { return record.scope === 'shop' ? '全店' : record.scope === 'product' ? '商品 · ' + (props.products.find(p => p.id === record.scope_id)?.title || '指定商品') : '场次 · ' + (props.sessions.find(s => s.id === record.scope_id)?.title || '指定场次') }
function recordState(record: KnowledgeRecord) { return record.deleted_at ? '已删除' : record.expires_at && Date.parse(record.expires_at) <= Date.now() ? '已过期' : '可检索' }
async function save() {
  if (busy.value) return; formError.value = ''
  try {
    if (!form.title.trim() || !form.content.trim() || !form.source.trim()) throw new Error('标题、内容和核验来源都需要填写。')
    if (form.scope !== 'shop' && !form.scopeId) throw new Error('请选择适用商品或场次。')
    const body = { shop_id: props.shopId, title: form.title.trim(), content: form.content.trim(), kind: form.kind, source: form.source.trim(), scope: form.scope, scope_id: form.scope === 'shop' ? null : form.scopeId, expires_at: form.expires ? new Date(form.expires).toISOString() : null, version: editing.value?.version ?? 0 }
    busy.value = true; await props.api.request(editing.value ? '/knowledge-records/' + editing.value.id : '/knowledge-records', { method: editing.value ? 'PUT' : 'POST', body }); open.value = false; await load(); await props.reload(); props.notify('知识已保存；只有范围匹配且未过期的资料会参与后续回复。')
  } catch (cause) { formError.value = errorMessage(cause) } finally { busy.value = false }
}
async function remove() { if (!deleting.value || busy.value) return; busy.value = true; formError.value = ''; try { await props.api.request('/knowledge-records/' + deleting.value.id, { method: 'DELETE', query: { shop_id: props.shopId, version: String(deleting.value.version) } }); deleting.value = null; await load(); await props.reload(); props.notify('记录已删除，可通过版本历史恢复为新版本。') } catch (cause) { formError.value = errorMessage(cause) } finally { busy.value = false } }
async function restored() { await load(); await props.reload(); props.notify('已恢复为新版本，请重新核对相关话术。') }
</script>
<template>
  <div class="page-heading"><div><div class="eyebrow">KNOWLEDGE & MEMORY</div><h1>知识与记忆</h1><p>带来源、范围与有效期的人工事实，让性格有稳定记忆。</p></div><button class="button primary" @click="edit(null)"><Icon name="plus" />新增记录</button></div><div class="info-strip">评论只用于当前回复，不会自动升级为长期记忆。这里保存你核验过的 FAQ 与人工记忆。</div><div v-if="error" class="alert error" role="alert">{{ error }}<button class="inline-button" @click="load">重试</button></div>
  <section class="panel"><div class="panel-toolbar"><div class="search-field"><Icon name="search" /><input v-model="search" placeholder="搜索标题与内容" aria-label="搜索知识" /></div><label class="checkbox-row"><input v-model="showDeleted" type="checkbox" />显示已删除</label><button class="button ghost small" @click="load">刷新</button></div><div v-if="loading" class="empty-state compact">正在读取记录…</div><div v-else-if="!filtered.length" class="empty-state"><Icon name="book" :size="32" /><h3>没有符合条件的记录</h3><p>新增常见问答或已核验的服务偏好，填写资料来源与适用范围。</p><button class="button secondary" @click="edit(null)">新增知识或记忆</button></div><div v-else class="knowledge-list"><article v-for="record in filtered" :key="record.id" class="knowledge-item"><div class="knowledge-copy"><div class="record-badges"><span class="badge neutral">{{ record.kind === 'faq' ? 'FAQ' : '人工记忆' }}</span><span class="badge" :class="recordState(record) === '可检索' ? 'success' : 'neutral'">{{ recordState(record) }}</span><span class="muted small-text">{{ scopeName(record) }} · v{{ record.version }}</span></div><h3>{{ record.title }}</h3><p>{{ record.content }}</p><div class="secondary-line">来源：{{ record.source }}<span v-if="record.expires_at"> · 有效至 {{ dateTime(record.expires_at) }}</span></div></div><div class="row-actions"><button v-if="!record.deleted_at" class="button ghost small" @click="edit(record)">编辑</button><button class="button ghost small" @click="history = record">历史{{ record.deleted_at ? ' / 恢复' : '' }}</button><button v-if="!record.deleted_at" class="button ghost small danger-text" @click="deleting = record; formError = ''">删除</button></div></article></div></section>
  <DialogShell v-if="open" :title="editing ? '编辑知识记录' : '新增知识或记忆'" @close="!busy && (open = false)"><form class="form-stack" @submit.prevent="save"><label>记录类型<select v-model="form.kind"><option value="faq">常见问题 FAQ</option><option value="memory">人工长期记忆</option></select></label><label>标题<input v-model="form.title" name="title" required maxlength="120" /></label><label>内容<textarea v-model="form.content" name="content" required rows="5" maxlength="4000" /></label><label>核验来源<input v-model="form.source" name="source" required maxlength="500" placeholder="例如商品手册版本、店铺规则或已确认的运营记录" /></label><label>适用范围<select v-model="form.scope" @change="form.scopeId = ''"><option value="shop">当前店铺</option><option value="product">指定商品</option><option value="session">指定场次</option></select></label><label v-if="form.scope === 'product'">选择商品<select v-model="form.scopeId" required><option value="">请选择</option><option v-for="product in products" :key="product.id" :value="product.id">{{ product.title }}</option></select></label><label v-if="form.scope === 'session'">选择场次<select v-model="form.scopeId" required><option value="">请选择</option><option v-for="session in sessions" :key="session.id" :value="session.id">{{ session.title }}</option></select></label><label>有效期<input v-model="form.expires" type="datetime-local" /><small>留空表示没有指定截止时间；到期后不再用于回复。</small></label><div v-if="formError" class="alert error" role="alert">{{ formError }}</div><div class="form-actions"><button type="button" class="button secondary" :disabled="busy" @click="open = false">取消</button><button class="button primary" :disabled="busy">{{ busy ? '保存中…' : '保存记录' }}</button></div></form></DialogShell>
  <DialogShell v-if="deleting" title="删除这条记录？" @close="!busy && (deleting = null)"><div class="form-stack"><p>“{{ deleting.title }}”会退出检索，依赖旧版本的任务需重新生成。历史仍可查看和恢复。</p><div v-if="formError" class="alert error" role="alert">{{ formError }}</div><div class="form-actions"><button class="button secondary" :disabled="busy" @click="deleting = null">取消</button><button class="button danger" :disabled="busy" @click="remove">{{ busy ? '删除中…' : '确认删除' }}</button></div></div></DialogShell>
  <HistoryDialog v-if="history" :api="api" :shop-id="shopId" kind="knowledge" :record-id="history.id" :current-version="history.version" :title="history.title" @close="history = null" @restored="restored" />
</template>
